using namespace Roadster;
static Hit Ground(const V3&s,const V3&d,double length,double radius){Hit h;if(d.z>=-1e-10)return h;const double depth=radius-s.z;const double t=depth>=0?0:(radius-s.z)/d.z;if(t<0||t>length)return h;h.bHit=true;h.CenterDist=t;h.Point=s+d*t-V3(0,0,radius);h.Dist=(h.Point-s).Dot(d);h.Normal={0,0,1};h.bStartPenetrating=depth>1e-8;h.PenetrationDepth=std::max(0.,depth);return h;}
static Vehicle Car(double speed=0,bool reverse=false){Vehicle v;v.Init(Trim::Rocket);v.Place({0,0,0},Quat());Inputs idle;for(int k=0;k<2000;++k)v.Step(.001,idle,Ground);v.Place(v.BodyOriginWorld(),v.Q,speed);if(reverse){Inputs in;in.bWantReverse=true;v.Step(.001,in,Ground);v.bReverseGear=true;}return v;}
struct Shape{float gas=0,brake=0,steer=0,pad=0;Inputs sample(float dt,float speed,float rawGas,float rawBrake,float rawSteer,bool keys,bool reverse){Inputs in;if(keys){gas+=RoadsterControls::Clamp(rawGas-gas,-10*dt,5*dt);brake+=RoadsterControls::Clamp(rawBrake-brake,-12*dt,7*dt);const bool returning=rawSteer==0||std::signbit(rawSteer)!=std::signbit(steer);steer=RoadsterControls::Smooth(steer,rawSteer,RoadsterControls::SteeringRate(speed,true,returning),dt);in.Steer=steer*RoadsterControls::SteeringAuthority(speed);}else{gas=RoadsterControls::Trigger(rawGas);brake=RoadsterControls::Trigger(rawBrake);const float x=RoadsterControls::Curve(rawSteer,.10f,1.5f);pad=RoadsterControls::Smooth(pad,x,RoadsterControls::SteeringRate(speed,false,std::fabs(x)<.01f),dt);in.Steer=pad*RoadsterControls::SteeringAuthority(speed);}in.Throttle=reverse?brake:gas;in.Brake=reverse?gas:brake;in.bWantReverse=reverse;return in;}};
struct Case{const char*Name;double Speed,Seconds;int Pattern,Fps;bool Keys,Reverse,ESC;double Lateral=0,Yaw=0;};
int main(int argc,char**argv){const char*tag=argc>1?argv[1]:"baseline";std::ofstream csv(std::string(tag)+"-telemetry.csv"),out(std::string(tag)+"-metrics.csv");csv<<std::setprecision(10)<<"case,t_s,x_m,y_m,speed_mps,vfwd_mps,side_deg,yaw_radps,steer_request,steer_fl_rad,steer_fr_rad,alpha_fl_deg,alpha_rl_deg,kappa_rl,kappa_rr,tcs_rl,tcs_rr,fx_rl_N,fy_rl_N,load_fl_N,load_rl_N,fan_N,peak_grip_usage,bTC,bESC,contacts\n";out<<std::setprecision(12)<<"case,fps,keys,esc,speed_initial_mps,max_side_deg,max_yaw_radps,final_side_deg,final_yaw_radps,final_speed_mps,lateral_final_m,high_slip_seconds,saturation_seconds,max_rear_kappa,max_tcs_step,min_wheels,finite,peak_grip_usage,peak_lateral_g,max_rear_alpha_deg,high_rear_slip_seconds\n";
std::vector<Case> cases={{"keys-launch",0,8,0,60,true,false,true},{"analog-launch",0,8,0,60,false,false,true},{"keys-pulse10",10,5,1,60,true,false,true},{"keys-pulse20",20,5,1,60,true,false,true},{"keys-pulse35",35,5,1,60,true,false,true},{"keys-pulse60",60,5,1,60,true,false,true},{"keys-slalom20",20,8,2,60,true,false,true},{"analog-pulse20",20,5,3,60,false,false,true},{"analog-slalom35",35,8,4,60,false,false,true},{"brake35",35,6,5,60,true,false,true},{"reverse-right",-8,5,1,60,true,true,true},{"reverse-left",-8,5,6,60,true,true,true},{"lateral-right-ESC",20,4,7,60,false,false,true,3},{"lateral-left-ESC",20,4,7,60,false,false,true,-3},{"lateral-right-raw",20,4,7,60,false,false,false,3},{"lateral-left-raw",20,4,7,60,false,false,false,-3},{"yaw-right-ESC",20,4,7,60,false,false,true,0,.5},{"yaw-left-ESC",20,4,7,60,false,false,true,0,-.5},{"keys-slalom20-fps20",20,8,2,20,true,false,true},{"keys-slalom20-fps120",20,8,2,120,true,false,true},{"analog-slalom35-fps20",35,8,4,20,false,false,true},{"analog-slalom35-fps120",35,8,4,120,false,false,true},{"analog-full-pulse35",35,5,8,60,false,false,true},{"brake-steer35",35,5,9,60,false,false,true},{"boost-steer20",20,5,10,60,true,false,true}};
for(const Case&c:cases){Vehicle v=Car(c.Speed,c.Reverse);v.Set.bESC=c.ESC;
if(std::string(tag)=="raw" || std::string(tag)=="signonly")v.Set.bAssistedSteering=false;
v.V.y=c.Lateral;v.W.z=c.Yaw;Shape shape;const float frameDt=1.f/c.Fps;double clock=0,acc=0,peakSide=0,peakYaw=0,slipTime=0,satTime=0,peakK=0,peakTCStep=0,grip=0,peakLat=0,oldTC=1,peakRearAlpha=0,highRearSlip=0;int minWheels=4;bool finite=true;Inputs held;while(clock<c.Seconds){float g=0,b=0,s=0;const double t=clock;if(c.Pattern==0)g=1;if(c.Pattern==1||c.Pattern==6)s=t>.25&&t<1.25?(c.Pattern==6?-1:1):0;if(c.Pattern==2){g=1;if(t>.5&&t<5.5)s=std::sin((t-.5)*2*kPi*.5)>=0?1:-1;}if(c.Pattern==3){g=.22f;s=t>.25&&t<1.25?.4f:0;}if(c.Pattern==4){g=.22f;s=t>.5&&t<5.5?.4f*float(std::sin((t-.5)*2*kPi*.5)):0;}if(c.Pattern==5)b=v.T.ForwardSpeed>.3?1:0;if(c.Pattern==8){g=.22f;s=t>.25&&t<1.25?1.f:0;}if(c.Pattern==9){b=t>.25&&t<1.5?.7f:0;s=t>.25&&t<1.25?1.f:0;}if(c.Pattern==10){g=1;s=t>.25&&t<1.25?1.f:0;}held=shape.sample(frameDt,float(v.T.Speed),g,b,s,c.Keys,c.Reverse);if(c.Pattern==10&&t<1.25)held.Boost=1;acc+=frameDt;while(acc>=.001&&clock<c.Seconds){v.Step(.001,held,Ground);clock+=.001;acc-=.001;const V3 vb=v.Q.Unrotate(v.V);const double side=std::atan2(vb.y,std::max(.1,std::fabs(vb.x)))*180/kPi;const double yaw=v.Q.Unrotate(v.W).z;peakSide=std::max(peakSide,std::fabs(side));peakYaw=std::max(peakYaw,std::fabs(yaw));if(std::fabs(vb.x)>3&&std::fabs(side)>10)slipTime+=.001;double use=0;for(const auto&w:v.Wheels)use=std::max(use,w.GripUsage);if(use>.98)satTime+=.001;grip=std::max(grip,use);peakK=std::max(peakK,std::max(std::fabs(v.Wheels[2].Kappa),std::fabs(v.Wheels[3].Kappa)));peakTCStep=std::max(peakTCStep,std::fabs(v.Wheels[2].TCScale-oldTC));oldTC=v.Wheels[2].TCScale;peakLat=std::max(peakLat,std::fabs(v.T.AccelG.y));const double rearAlpha=std::max(std::fabs(v.Wheels[2].Alpha),std::fabs(v.Wheels[3].Alpha));peakRearAlpha=std::max(peakRearAlpha,rearAlpha*180/kPi);if(rearAlpha>2*std::tan(v.S.PeakSlipAngleDeg*kPi/180))highRearSlip+=.001;minWheels=std::min(minWheels,v.T.WheelsInContact);finite &=std::isfinite(v.X.Len())&&std::isfinite(v.V.Len())&&std::isfinite(v.W.Len());if(int(clock*1000)%20==0)csv<<c.Name<<','<<clock<<','<<v.X.x<<','<<v.X.y<<','<<v.T.Speed<<','<<v.T.ForwardSpeed<<','<<side<<','<<yaw<<','<<held.Steer<<','<<v.Wheels[0].Steer<<','<<v.Wheels[1].Steer<<','<<v.Wheels[0].Alpha*180/kPi<<','<<v.Wheels[2].Alpha*180/kPi<<','<<v.Wheels[2].Kappa<<','<<v.Wheels[3].Kappa<<','<<v.Wheels[2].TCScale<<','<<v.Wheels[3].TCScale<<','<<v.Wheels[2].Fx<<','<<v.Wheels[2].Fy<<','<<v.Wheels[0].Load<<','<<v.Wheels[2].Load<<','<<v.T.FanDownforceN<<','<<use<<','<<v.T.bTC<<','<<v.T.bESC<<','<<v.T.WheelsInContact<<'\n';}}
const V3 vb=v.Q.Unrotate(v.V);const double side=std::atan2(vb.y,std::max(.1,std::fabs(vb.x)))*180/kPi,yaw=v.Q.Unrotate(v.W).z;out<<c.Name<<','<<c.Fps<<','<<c.Keys<<','<<c.ESC<<','<<c.Speed<<','<<peakSide<<','<<peakYaw<<','<<side<<','<<yaw<<','<<v.T.Speed<<','<<v.X.y<<','<<slipTime<<','<<satTime<<','<<peakK<<','<<peakTCStep<<','<<minWheels<<','<<finite<<','<<grip<<','<<peakLat<<','<<peakRearAlpha<<','<<highRearSlip<<'\n';std::printf("%s peakSide=%.3fdeg finalSide=%.3fdeg peakYaw=%.3f finalYaw=%.4f speed=%.3f highSlip=%.3fs sat=%.3fs rearK=%.4f minW=%d finite=%d rearAlpha=%.3fdeg highRear=%.3fs\n",c.Name,peakSide,side,peakYaw,yaw,v.T.Speed,slipTime,satTime,peakK,minWheels,finite,peakRearAlpha,highRearSlip);}
}


